    "src/staking/InfraredBERADepositorV2.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.26;

import {IBeaconDeposit} from "@berachain/pol/interfaces/IBeaconDeposit.sol";
import {Errors, Upgradeable} from "src/utils/Upgradeable.sol";
import {IInfraredBERAV2} from "src/interfaces/IInfraredBERAV2.sol";
import {IInfraredBERAWithdrawor} from
    "src/interfaces/IInfraredBERAWithdrawor.sol";
import {InfraredBERAConstants} from "src/staking/InfraredBERAConstants.sol";
import {BeaconRootsVerify} from "src/utils/BeaconRootsVerify.sol";

/// @title InfraredBERADepositorV2
/// @notice Depositor to deposit BERA to CL for Infrared liquid staking token
contract InfraredBERADepositorV2 is Upgradeable {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       STORAGE                              */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice https://eth2book.info/capella/part2/deposits-withdrawals/withdrawal-processing/
    uint8 public constant ETH1_ADDRESS_WITHDRAWAL_PREFIX = 0x01;
    /// @notice The Deposit Contract Address for Berachain
    address public DEPOSIT_CONTRACT;
    /// @notice the main InfraredBERA contract address
    address public InfraredBERA;
    /// @notice the queued amount of BERA to be deposited
    uint256 public reserves;

    /// @notice Minimum deposit for a validator to become active.
    uint256 public minActivationDeposit;

    /// Reserve storage slots for future upgrades for safety
    uint256[39] private __gap;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          EVENTS                            */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Emitted when a new deposit queued
    /// @param amount New deposit amount in BERA
    event Queue(uint256 amount);

    /// @notice Emitted when a consensus layer deposit queued to a validator
    /// @param pubkey Public key af validator to deposit to
    /// @param amount Validator deposit amount
    event Execute(bytes pubkey, uint256 amount);

    /// @notice Emitted when min activation deposit is updated by governance
    /// @param newMinActivationDeposit New value for min activation deposit to guarentee set inclusion
    event MinActivationDepositUpdated(uint256 newMinActivationDeposit);

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       INITIALIZATION                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Initialize V2
    function initializeV2() external onlyGovernor {
        // needs to be enough to guarentee activation (250k) + inclusion in active set (depends on competition)
        minActivationDeposit = 500_000 ether;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                      QUEUE, EXECUTE                        */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Queues a deposit by sending BERA to this contract and storing the amount
    /// in reserves account for beacon deposits on batch
    function queue() external payable {
        /// @dev can only be called by InfraredBERA for adding to the reserves and by withdrawor for rebalancing
        /// when validators get kicked out of the set, TODO: link the set kickout code.
        if (
            msg.sender != InfraredBERA
                && msg.sender != IInfraredBERAV2(InfraredBERA).withdrawor()
        ) {
            revert Errors.Unauthorized(msg.sender);
        }

        // @dev accumulate the amount of BERA to be deposited with `execute`
        reserves += msg.value;

        emit Queue(msg.value);
    }

    /// @notice Executes initial deposit for 10k bera to the specified pubkey.
    /// @param pubkey The pubkey of the validator to deposit for
    /// @dev Only callable by the keeper
    /// @dev Only callable if the deposits are enabled
    /// @dev Only callable for initial deposit
    function executeInitialDeposit(bytes calldata pubkey) external onlyKeeper {
        // check if pubkey is a valid validator being tracked by InfraredBERA
        if (!IInfraredBERAV2(InfraredBERA).validator(pubkey)) {
            revert Errors.InvalidValidator();
        }

        // The validator balance must be zero
        if (IInfraredBERAV2(InfraredBERA).stakes(pubkey) != 0) {
            revert Errors.AlreadyInitiated();
        }

        // @dev determin what to set the operator, if the operator is not set we know this is the first deposit and we should set it to infrared.
        // if not we know this is the second or subsequent deposit (subject to internal test below) and we should set the operator to address(0).
        address operatorBeacon =
            IBeaconDeposit(DEPOSIT_CONTRACT).getOperator(pubkey);
        address operator = IInfraredBERAV2(InfraredBERA).infrared();
        // check if first beacon deposit by checking if the registered operator is set
        if (operatorBeacon != address(0)) {
            revert Errors.AlreadyInitiated();
        }

        uint256 amount = InfraredBERAConstants.INITIAL_DEPOSIT;

        // @notice load the signature for the pubkey. This is only used for the first deposit but can be re-used safley since this is checked only on the first deposit.
        // https://github.com/berachain/beacon-kit/blob/395085d18667e48395503a20cd1b367309fe3d11/state-transition/core/state_processor_staking.go#L101
        bytes memory signature =
            IInfraredBERAV2(InfraredBERA).signatures(pubkey);
        if (signature.length == 0) {
            revert Errors.InvalidSignature();
        }

        // @notice ethereum/consensus-specs/blob/dev/specs/phase0/validator.md#eth1_address_withdrawal_prefix
        // @dev similar to the signiture above, this is only used for the first deposit but can be re-used safley since this is checked only on the first deposit.
        bytes memory credentials = abi.encodePacked(
            ETH1_ADDRESS_WITHDRAWAL_PREFIX,
            uint88(0), // 11 zero bytes
            IInfraredBERAV2(InfraredBERA).withdrawor()
        );

        /// @dev reduce the reserves by the amount deposited.
        reserves -= amount;

        /// @dev register the increase in stake to the validator.
        IInfraredBERAV2(InfraredBERA).register(pubkey, int256(amount));

        // @dev deposit the BERA to the deposit contract.
        // @dev the amount being divided by 1 gwei is checked inside.
        IBeaconDeposit(DEPOSIT_CONTRACT).deposit{value: amount}(
            pubkey, credentials, signature, operator
        );

        emit Execute(pubkey, amount);
    }

    /// @notice Executes a deposit to the deposit contract for the specified pubkey and amount.
    /// @param header The Beacon block header data
    /// @param validator The full validator struct to deposit for
    /// @param validatorMerkleWitness Merkle witness for validator
    /// @param balanceMerkleWitness Merkle witness for balance container
    /// @param validatorIndex index of validator
    /// @param balanceLeaf 32 bytes chunk including packed balance
    /// @param amount The amount of BERA to deposit
    /// @param nextBlockTimestamp timestamp of following block to header to verify parent root in beaconroots call
    /// @dev Only callable by the keeper
    /// @dev Only callable if the deposits are enabled
    /// @dev Only for deposits subsequent to initialization
    function execute(
        BeaconRootsVerify.BeaconBlockHeader calldata header,
        BeaconRootsVerify.Validator calldata validator,
        bytes32[] calldata validatorMerkleWitness,
        bytes32[] calldata balanceMerkleWitness,
        uint256 validatorIndex,
        bytes32 balanceLeaf,
        uint256 amount,
        uint256 nextBlockTimestamp
    ) external onlyKeeper {
        // cache pubkey
        bytes memory pubkey = validator.pubkey;

        // check if pubkey is a valid validator being tracked by InfraredBERA
        if (!IInfraredBERAV2(InfraredBERA).validator(pubkey)) {
            revert Errors.InvalidValidator();
        }

        // The amount must be a multiple of 1 gwei as per the deposit contract, cannot be more eth than we have, and must be at least the minimum deposit amount.
        if (amount == 0 || (amount % 1 gwei) != 0 || amount > reserves) {
            revert Errors.InvalidAmount();
        }

        // check proof data is not stale
        if (
            block.timestamp
                > nextBlockTimestamp
                    + IInfraredBERAV2(InfraredBERA).proofTimestampBuffer()
        ) revert Errors.StaleProof();

        // Verify stake
        uint256 stake = IInfraredBERAV2(InfraredBERA).stakes(pubkey);
        // verify stake amount againt CL via beacon roots proof
        if (
            !BeaconRootsVerify.verifyValidatorBalance(
                header,
                balanceMerkleWitness,
                validatorIndex,
                stake
                    + IInfraredBERAWithdrawor(
                        IInfraredBERAV2(InfraredBERA).withdrawor()
                    ).getTotalPendingWithdrawals(keccak256(pubkey)),
                balanceLeaf,
                nextBlockTimestamp
            )
        ) {
            revert Errors.BalanceMissmatch();
        }

        // cache the withdrawor address since we will be using it multiple times.
        address withdrawor = IInfraredBERAV2(InfraredBERA).withdrawor();

        // verify withdrawal address is set correctly against consensus layer
        // note: since this verifies all validator info, all subsequent validator checks in this call can be assumed to match CL
        if (
            // note: beaconroots call above, so we can now internally verify against state root
            !BeaconRootsVerify.verifyValidatorWithdrawalAddress(
                header.stateRoot,
                validator,
                validatorMerkleWitness,
                validatorIndex,
                withdrawor
            )
        ) revert Errors.InvalidWithdrawalAddress();

        // Verify validator has not been exited
        // Default state for all epoch values is type(uint64).max (https://eth2book.info/latest/part3/config/constants/)
        if (validator.exitEpoch != type(uint64).max) {
            revert Errors.AlreadyExited();
        }

        // The validator balance + amount must not surpase MaxEffectiveBalance of 10 million BERA.
        if (stake + amount > InfraredBERAConstants.MAX_EFFECTIVE_BALANCE) {
            revert Errors.ExceedsMaxEffectiveBalance();
        }

        address operator = IInfraredBERAV2(InfraredBERA).infrared();
        {
            // @dev determin what to set the operator, if the operator is not set we know this is the first deposit and we should set it to infrared.
            // if not we know this is the second or subsequent deposit (subject to internal test below) and we should set the operator to address(0).
            address operatorBeacon =
                IBeaconDeposit(DEPOSIT_CONTRACT).getOperator(pubkey);

            // check if first beacon deposit by checking if the registered operator is set
            if (operatorBeacon == address(0)) {
                revert Errors.NotInitialized();
            }
            // Not first deposit. Ensure the correct operator is set for subsequent deposits
            if (operatorBeacon != operator) {
                revert Errors.UnauthorizedOperator();
            }
        }

        // check whether first deposit via internal logic to protect against bypass beacon deposit attack
        if (!IInfraredBERAV2(InfraredBERA).staked(pubkey)) {
            revert Errors.OperatorAlreadySet();
        }

        // ensure second deposit is enough to meet active validator set
        if (stake < minActivationDeposit) {
            if (amount < minActivationDeposit - stake) {
                revert Errors.DepositMustBeGreaterThanMinActivationBalance();
            }
        }

        // A nuance of berachain is that subsequent deposits set operator to address(0)
        operator = address(0);

        // @notice load the signature for the pubkey. This is only used for the first deposit but can be re-used safley since this is checked only on the first deposit.
        // https://github.com/berachain/beacon-kit/blob/395085d18667e48395503a20cd1b367309fe3d11/state-transition/core/state_processor_staking.go#L101
        bytes memory signature =
            IInfraredBERAV2(InfraredBERA).signatures(pubkey);
        if (signature.length == 0) {
            revert Errors.InvalidSignature();
        }

        // @notice ethereum/consensus-specs/blob/dev/specs/phase0/validator.md#eth1_address_withdrawal_prefix
        // @dev similar to the signiture above, this is only used for the first deposit but can be re-used safley since this is checked only on the first deposit.
        bytes memory credentials = abi.encodePacked(
            ETH1_ADDRESS_WITHDRAWAL_PREFIX,
            uint88(0), // 11 zero bytes
            withdrawor
        );

        /// @dev reduce the reserves by the amount deposited.
        reserves -= amount;

        /// @dev register the increase in stake to the validator.
        IInfraredBERAV2(InfraredBERA).register(pubkey, int256(amount));

        // @dev deposit the BERA to the deposit contract.
        // @dev the amount being divided by 1 gwei is checked inside.
        IBeaconDeposit(DEPOSIT_CONTRACT).deposit{value: amount}(
            pubkey, credentials, signature, operator
        );

        emit Execute(pubkey, amount);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       ADMIN                                */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    function setMinActivationDeposit(uint256 _minActivationDeposit)
        external
        onlyGovernor
    {
        if (
            _minActivationDeposit
                >= InfraredBERAConstants.MAX_EFFECTIVE_BALANCE
                    - InfraredBERAConstants.INITIAL_DEPOSIT
        ) revert Errors.ExceedsMaxEffectiveBalance();
        minActivationDeposit = _minActivationDeposit;
        emit MinActivationDepositUpdated(_minActivationDeposit);
    }
}
"
    },
    "src/interfaces/IInfraredBERAWithdrawor.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IInfraredBERAWithdrawor {
    /// @notice Emitted when a withdrawal is queued
    /// @param receiver The address that will receive the withdrawn BERA
    /// @param nonce The unique identifier for this withdrawal request
    /// @param amount The amount of BERA to be withdrawn
    event Queue(address indexed receiver, uint256 nonce, uint256 amount);

    /// @notice Emitted when a withdrawal is executed
    /// @param pubkey The validator's public key
    /// @param amount The amount of BERA withdrawn
    event Execute(bytes pubkey, uint256 amount);

    /// @notice Emitted when a queue is processed
    /// @param receiver The address receiving the withdrawn BERA
    /// @param nonce The nonce of the processed withdrawal
    /// @param amount The amount of BERA processed
    event Process(address indexed receiver, uint256 nonce, uint256 amount);

    /// @notice Emitted when a withdrawal request range is processed
    /// @param startRequestId First request processed
    /// @param finishRequestId Last request processed
    event ProcessRange(uint256 startRequestId, uint256 finishRequestId);

    /// @notice Emitted when a claim is processed
    /// @param receiver The address receiving the withdrawn BERA
    /// @param nonce The nonce of the processed withdrawal
    /// @param amount The amount of BERA processed
    event Claimed(address indexed receiver, uint256 nonce, uint256 amount);

    /// @notice Emitted when funds are swept from a force-exited validator
    /// @param receiver The address receiving the swept BERA
    /// @param amount The amount of BERA swept
    event Sweep(address indexed receiver, uint256 amount);

    /// @notice Emitted when min activation balance is updated by governance
    /// @param newMinActivationBalance New value for min activation balance to maintain activity
    event MinActivationBalanceUpdated(uint256 newMinActivationBalance);

    /// @notice The address of the InfraredBERA contract
    function InfraredBERA() external view returns (address);

    /// @notice Sweeps forced withdrawals to InfraredBERA to re-stake principal
    /// @param pubkey The validator's public key to sweep funds from
    /// @dev Only callable when withdrawals are disabled and by keeper
    // function sweep(bytes calldata pubkey) external;

    /// @notice State of a withdrawal request ticket.
    /// @dev QUEUED: Ticket is queued and awaiting processing. PROCESSED: Ticket is finalized and claimable (or rebalanced for depositor). CLAIMED: Ticket has been claimed by the receiver.
    enum RequestState {
        QUEUED,
        PROCESSED,
        CLAIMED
    }

    /// @notice The request struct for withdrawal requests.
    /// @param state records whether queued, processed or claimed
    /// @param timestamp The block.timestamp at which the withdraw request was issued.
    /// @param receiver The address of the receiver of the withdrawn BERA funds.
    /// @param amount The amount of BERA to be claimed by receiver.
    /// @param accumulatedAmount Running total amount withdrawn inclusive of this ticket.
    struct WithdrawalRequest {
        RequestState state;
        uint88 timestamp;
        address receiver;
        uint128 amount;
        uint128 accumulatedAmount;
    }

    /// @notice Mapping of request IDs to withdrawal request tickets.
    /// @dev Key is the `requestId` (starting at 1), and value is the `WithdrawalRequest` struct.
    function requests(uint256 nonce)
        external
        view
        returns (
            RequestState state,
            uint88 timestamp,
            address receiver,
            uint128 amount,
            uint128 accumulatedAmount
        );

    /// @notice Struct to track pending withdrawals with expiry
    struct PendingWithdrawal {
        uint160 amount;
        uint96 expiryBlock;
        bytes32 pubkeyHash;
    }

    /// @notice Sums all current pending withdrawals as helper for keeper to calculate how much needs to be executed next
    /// @param pubkeyHash keccak256 of public key for validator to get pending withdrawals for
    /// @return total Sum amount in bera, pending on CL to return to contract
    /// @dev Iterates through pending withdrawals, counting only those that have not expired (fulfilled)
    function getTotalPendingWithdrawals(bytes32 pubkeyHash)
        external
        view
        returns (uint256 total);

    /// @notice Amount of BERA internally set aside to process withdraw compile requests from funds received on successful requests
    function reserves() external view returns (uint256);

    /// @notice Retrieves the current fee required by the withdrawal precompile.
    /// @return fee The fee (in wei) required for a withdrawal request.
    /// @dev Performs a static call to the precompile. Reverts if the call fails or the response is invalid (not 32 bytes).
    function getFee() external view returns (uint256 fee);

    /// @notice Returns the total amount of BERA queued for withdrawal across all unprocessed tickets.
    /// @return queuedAmount The total amount of BERA (in wei) in `QUEUED` tickets from `requestsFinalisedUntil + 1` to `requestLength`.
    /// @dev Calculates the difference between the cumulative amount at `requestLength` and `requestsFinalisedUntil`.
    /// @dev Returns 0 if `requestLength == requestsFinalisedUntil` (no unprocessed tickets) or `requestLength == 0` (no tickets queued).
    /// @dev Assumes tickets from `requestsFinalisedUntil + 1` to `requestLength` are in `QUEUED` state, as enforced by `process`.
    function getQueuedAmount() external view returns (uint256 queuedAmount);

    /// @notice Calculates the highest request ID that can be finalized by `process` given the current reserves.
    /// @return newRequestsFinalisedUntil The highest `requestId` (inclusive) that can be processed without exceeding available reserves, or 0 if no tickets can be processed.
    /// @dev Iterates through unprocessed tickets (`requestsFinalisedUntil + 1` to `requestLength`) to find the maximum number of requests whose cumulative amount does not exceed `reserves()`.
    /// @dev Returns `requestsFinalisedUntil` if no additional tickets can be processed due to insufficient reserves.
    function getRequestsToProcess()
        external
        view
        returns (uint256 newRequestsFinalisedUntil);

    /// @notice Queues a withdraw request from InfraredBERA
    /// @param receiver The address to receive withdrawn funds
    /// @param amount The amount of funds to withdraw
    /// @return nonce The unique identifier for this withdrawal request
    /// @dev Requires msg.value to cover minimum withdrawal fee
    function queue(address receiver, uint256 amount)
        external
        returns (uint256 nonce);

    /// @notice Executes a withdraw request to withdraw precompile
    /// @param pubkey The validator's public key to withdraw from
    /// @param amount The amount of BERA to withdraw
    /// @dev Payable to cover any additional fees required by precompile
    /// @dev Only callable by keeper
    // function execute(bytes calldata pubkey, uint256 amount) external payable;

    /// @notice Finalizes a range of withdrawal requests, marking them as claimable or rebalancing to the depositor.
    /// @param newRequestsFinalisedUntil The highest `requestId` to finalize (inclusive).
    /// @dev Reverts if:
    /// - `newRequestsFinalisedUntil` exceeds `requestLength`.
    /// - `newRequestsFinalisedUntil` is less than or equal to `requestsFinalisedUntil`.
    /// - Available reserves are insufficient for the total amount to finalize.
    /// @dev Accumulates amounts for depositor rebalancing into a single call to `InfraredBERADepositor.queue`.
    /// @dev Updates `totalClaimable` for non-depositor tickets.
    function process(uint256 newRequestsFinalisedUntil) external;

    /// @notice Claims a finalized withdrawal request for a user.
    /// @param requestId The ID of the withdrawal request to claim.
    /// @dev Reverts if:
    /// - `requestId` exceeds `requestsFinalisedUntil` (not finalized).
    /// - Ticket is not in `PROCESSED` state or belongs to the depositor.
    /// @dev Transitions the ticket to `CLAIMED` and transfers the amount to the receiver.
    function claim(uint256 requestId) external;

    /// @notice Claims multiple finalized withdrawal requests in a single transaction.
    /// @param requestIds An array of request IDs to claim.
    /// @param receiver recipient address of all requestId's
    /// @dev Reverts if:
    /// - Any `requestId` exceeds `requestsFinalisedUntil` (not finalized).
    /// - Any ticket is not in `PROCESSED` state or belongs to the depositor.
    /// @dev Transitions each ticket to `CLAIMED` and transfers the total amount to the caller.
    /// @dev Emits a `Claimed` event for each claimed ticket.
    function claimBatch(uint256[] calldata requestIds, address receiver)
        external;
}
"
    },
    "src/interfaces/IInfraredBERAFeeReceivor.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {IInfrared} from "src/depreciated/interfaces/IInfrared.sol";

interface IInfraredBERAFeeReceivor {
    /// @notice Emitted when accumulated rewards are swept to InfraredBERA
    /// @param receiver The address receiving the swept BERA
    /// @param amount The amount of BERA swept
    /// @param fees The amount of fees taken
    event Sweep(address indexed receiver, uint256 amount, uint256 fees);

    /// @notice Emitted when shareholder fees are collected
    /// @param receiver The address receiving the collected fees
    /// @param amount The amount of fees collected
    /// @param sharesMinted The amount of iBERA shares minted
    event Collect(
        address indexed receiver, uint256 amount, uint256 sharesMinted
    );

    /// @notice The address of the `InfraredBERA.sol` contract
    function InfraredBERA() external view returns (address);

    /// @notice The `Infrared.sol` contract address
    function infrared() external view returns (IInfrared);

    /// @notice Accumulated protocol fees in contract to be claimed
    function shareholderFees() external view returns (uint256);

    /// @notice Amount of BERA swept to InfraredBERA and fees taken for protool on next call to sweep
    /// @return amount The amount of BERA forwarded to InfraredBERA on next sweep
    /// @return fees The protocol fees taken on next sweep
    function distribution()
        external
        view
        returns (uint256 amount, uint256 fees);

    /// @notice Sweeps accumulated coinbase priority fees + MEV to InfraredBERA to autocompound principal
    /// @return amount The amount of BERA forwarded to InfraredBERA
    /// @return fees The total fees taken
    function sweep() external returns (uint256 amount, uint256 fees);

    /// @notice Collects accumulated shareholder fees
    /// @dev Reverts if msg.sender is not `InfraredBera.sol` contract
    /// @return sharesMinted The amount of iBERA shares minted and sent to the `Infrared.sol`
    function collect() external returns (uint256 sharesMinted);

    /// @notice Initializer function (replaces constructor)
    /// @param _gov Address for admin / gov to upgrade
    /// @param _keeper Address for keeper
    /// @param ibera Address for InfraredBERA
    /// @param _infrared Address for Infrared
    function initialize(
        address _gov,
        address _keeper,
        address ibera,
        address _infrared
    ) external;
}
"
